window.DV_LANG=window.DV_LANG||{};window.DV_LANG["sankey"]={"type":"sankey","features":{"main_path":{"label_zh":"主路径","requires":["subject","source","target","value","share","pct"],"words":[{"en":"go straight","zh":"直接流向","register":"spoken","grammar":"go straight to/into + 名词","collocations":["goes straight to checkout"],"note_zh":"口语，强调不经中间环节。"},{"en":"the bulk of","zh":"大部分","register":"spoken","grammar":"the bulk of + 名词","collocations":["the bulk of traffic"],"note_zh":"比 most of 更强调体量。"},{"en":"flow","zh":"流量；流动","register":"neutral","grammar":"n./v.；flow from X to Y","collocations":["traffic flow","cash flow"],"note_zh":"桑基图表示规模的首选词。"},{"en":"account for","zh":"占（比例）","register":"written","grammar":"account for + 比例","collocations":["account for 62 percent"],"note_zh":"只接比例，不接具体来源。"}],"patterns":[{"id":"sk-mp-a2","level":"a2","register":"spoken","frame":"Most of {subject} goes from {source} to {target}.","zh_frame":"大部分{subject}从 {source} 流向 {target}。","note_zh":"go from...to...。"},{"id":"sk-mp-b1","level":"b1","register":"written","frame":"{subject} flows mainly from {source} to {target}, at {share} of the total.","zh_frame":"{subject}主要从 {source} 流向 {target}，占总量 {share}。","note_zh":"at + 比例 + of + 整体。"}],"compare":["flow-vs-move","through-vs-into"],"traps":[{"wrong_en":"Traffic from the homepage flows the search page.","right_en":"Traffic flows from the homepage to the search page.","why_zh":"flow 后必须带 from ... to ...。"}],"registers":{"general":"Most of {subject} goes straight from {source} to {target}.","ielts":"{subject} flows mainly from {source} to {target}, accounting for {share} of the total.","business":"The main path is {source} to {target}: {share} of the total, and the cheapest route to protect."}},"secondary_path":{"label_zh":"次要路径","requires":["subject","source","target","value","share","pct"],"words":[{"en":"trickle","zh":"少量持续流入","register":"spoken","grammar":"trickle into/through","collocations":["trickle into the app"],"note_zh":"强调量小且持续。"},{"en":"a slice of","zh":"一小部分","register":"spoken","grammar":"a slice of + 名词","collocations":["a slice of traffic"],"note_zh":"口语，比 a share 更有画面。"},{"en":"a share of","zh":"份额","register":"neutral","grammar":"a share of + 名词","collocations":["a small share of"],"note_zh":"统计与日常通用。"},{"en":"divert","zh":"分流；改道","register":"written","grammar":"divert + 名词 + from X to Y","collocations":["divert 8 percent of traffic"],"note_zh":"常含“从原路挪走”。"}],"patterns":[{"id":"sk-sp-a2","level":"a2","register":"spoken","frame":"A small share of {subject} goes from {source} to {target}.","zh_frame":"一小部分{subject}从 {source} 流向 {target}。","note_zh":"a small share 口语。"},{"id":"sk-sp-b1","level":"b1","register":"written","frame":"Only {share} of {subject} reaches {target} from {source}.","zh_frame":"仅 {share} 的{subject}从 {source} 到达 {target}。","note_zh":"only 前置强调量小。"}],"compare":["main-source-vs-top","flow-vs-move"],"traps":[{"wrong_en":"12 percent users came from referrals.","right_en":"12 percent of users came from referrals.","why_zh":"percent 后必须接 of + 名词。"}],"registers":{"general":"A small share of {subject} also trickles from {source} to {target}.","ielts":"{source} accounts for a minor proportion of {subject} to {target}, at {share}.","business":"{source} is a small but cheap path into {target}; keep it open."}},"drop_off":{"label_zh":"流失","requires":["subject","source","target","value","share","pct"],"words":[{"en":"drop off","zh":"掉队；流失","register":"spoken","grammar":"drop off at/after + 名词","collocations":["drop off at sign-up"],"note_zh":"口语，指流程中流失。"},{"en":"fall away","zh":"逐渐消失","register":"spoken","grammar":"fall away after + 名词","collocations":["fall away after checkout"],"note_zh":"强调逐步而非一次性。"},{"en":"drop-off","zh":"流失（量）","register":"neutral","grammar":"a drop-off in + 名词","collocations":["a drop-off in sign-ups"],"note_zh":"图表标签的标准名词形式。"},{"en":"attrition","zh":"自然流失","register":"written","grammar":"attrition between X and Y","collocations":["high attrition"],"note_zh":"正式，强调持续缓慢。"}],"patterns":[{"id":"sk-do-a2","level":"a2","register":"spoken","frame":"Only {share} of {subject} reaches {target}; the rest drops off.","zh_frame":"只有 {share} 的{subject}到达 {target}，其余流失。","note_zh":"the rest 指剩余部分。"},{"id":"sk-do-b1","level":"b1","register":"written","frame":"Attrition between {source} and {target} removes {share} of {subject}.","zh_frame":"{source}到 {target}之间流失了 {share} 的{subject}。","note_zh":"between...and... 表示流失区间。"}],"compare":["through-vs-into","flow-vs-move"],"traps":[{"wrong_en":"Users drop off from the payment page to the confirmation page.","right_en":"Users drop off between the payment page and the confirmation page.","why_zh":"流失发生在两点之间，用 between ... and ...。"}],"registers":{"general":"Only {share} of {subject} reaches {target}; the rest drops off.","ielts":"Attrition between {source} and {target} removes {share} of {subject}.","business":"We lose {share} of {subject} before {target}; that is the cheapest leak to fix."}},"merge":{"label_zh":"汇合","requires":["subject","source","target","value","share"],"words":[{"en":"come together","zh":"汇合","register":"spoken","grammar":"come together at + 节点","collocations":["streams come together"],"note_zh":"口语，画面感强。"},{"en":"pool","zh":"汇集","register":"spoken","grammar":"pool + 名词 + into","collocations":["pool orders"],"note_zh":"强调集中调配。"},{"en":"merge","zh":"合并","register":"neutral","grammar":"merge into + 名词","collocations":["merge into one stream"],"note_zh":"通用术语，本身含 together。"},{"en":"converge","zh":"汇聚","register":"written","grammar":"converge at/on","collocations":["converge at the depot"],"note_zh":"书面，强调多点归一。"}],"patterns":[{"id":"sk-mg-a2","level":"a2","register":"spoken","frame":"Two sources come together at {target}.","zh_frame":"两个来源在 {target} 汇合。","note_zh":"come together at。"},{"id":"sk-mg-b1","level":"b1","register":"written","frame":"Flows from {source} and other sources converge at {target}, at {share} of the total.","zh_frame":"来自 {source} 等的流量在 {target} 汇合，占总量的 {share}。","note_zh":"converge at + 节点。"}],"compare":["flow-vs-move","main-source-vs-top"],"traps":[{"wrong_en":"The two streams merge together into the warehouse.","right_en":"The two streams merge into the warehouse.","why_zh":"merge 已含 together，再加语义重复。"}],"registers":{"general":"Flows from {source} and elsewhere come together at {target}.","ielts":"Several flows converge at {target}, with {source} contributing {share}.","business":"Everything merges at {target}, which makes it the place to control the flow."}},"split":{"label_zh":"拆分","requires":["subject","source","target","value","share","pct"],"words":[{"en":"split","zh":"拆分","register":"spoken","grammar":"split into + 名词","collocations":["split into two lanes"],"note_zh":"口语通用。"},{"en":"break down","zh":"细分","register":"spoken","grammar":"break down into/by","collocations":["break down by channel"],"note_zh":"强调按维度拆开。"},{"en":"divide into","zh":"分为","register":"neutral","grammar":"divide X into Y","collocations":["divide traffic into three"],"note_zh":"中性，带数学味。"},{"en":"allocate","zh":"分配","register":"written","grammar":"allocate + 名词 + to","collocations":["allocate 30 percent to"],"note_zh":"含主动决策，不是自然分流。"}],"patterns":[{"id":"sk-sp-a2","level":"a2","register":"spoken","frame":"{source} splits into {target} and other paths.","zh_frame":"{source}分成 {target} 和其他路径。","note_zh":"split into。"},{"id":"sk-sp-b1","level":"b1","register":"written","frame":"Of the {subject} leaving {source}, {share} is allocated to {target}.","zh_frame":"离开 {source} 的{subject}中，{share}分配给 {target}。","note_zh":"of + 整体，前置比例。"}],"compare":["through-vs-into","flow-vs-move"],"traps":[{"wrong_en":"The budget splits in three channels.","right_en":"The budget splits into three channels.","why_zh":"分成几份用 into。"}],"registers":{"general":"{source} splits into {target} and other paths.","ielts":"Of the {subject} leaving {source}, {share} is allocated to {target}.","business":"{source} splits {pct} percent to {target}; the rest goes elsewhere."}}},"comparisons":[{"id":"flow-vs-move","a":"flow","b":"move","meaning_zh":"flow 指系统内成规模的流动；move 泛指移动。","grammar_zh":"flow from X to Y；move to/into + 地点","collocations_zh":"traffic flow / move house","usage_zh":"桑基图描述人、钱、货的规模用 flow；move 不带量感。","examples":[{"en":"Most users flow from search to checkout, while only a few move to the help page.","zh":"多数用户从搜索流向结算，只有少数转到帮助页。"}]},{"id":"account-for-vs-make-up","a":"account for","b":"make up","meaning_zh":"都表构成比例；make up 更口语，且 make up for 意为“弥补”。","grammar_zh":"account for + 比例；make up + 比例","collocations_zh":"account for 30 percent / make up half","usage_zh":"报告用 account for；口语用 make up，但不要说 make up for the total。","examples":[{"en":"Mobile accounts for 68 percent of traffic, and app installs make up most of that.","zh":"移动端占流量的 68%，其中大部分是应用安装。"}]},{"id":"through-vs-into","a":"through","b":"into","meaning_zh":"through 经过中间节点；into 进入终点。","grammar_zh":"go through X to Y；go into Y","collocations_zh":"through the checkout / into the warehouse","usage_zh":"中间环节用 through，最终落点用 into。","examples":[{"en":"Goods move through the sorting hub into the local warehouse.","zh":"货物经分拣中心进入本地仓库。"}]},{"id":"main-source-vs-top","a":"main source","b":"top source","meaning_zh":"main 指主要来源（量或重要性）；top 指排名第一。","grammar_zh":"the main source of + 名词；the top source of + 名词","collocations_zh":"main source of traffic / top source of revenue","usage_zh":"只有一个第一时用 top；强调依赖关系用 main。","examples":[{"en":"Search is our main source of sign-ups and the top source of revenue.","zh":"搜索是注册的主要来源，也是收入的第一来源。"}]}]};
